"use client";

import { useId, useState } from "react";

import { AlertTriangleIcon, CircleCheckIcon, CircleXIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { RadioGroup } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { formatWhole } from "../lib/format";
import { mean } from "../lib/plot";
import { STATUS_TEXT, STATUS_WORD, type Status } from "../lib/status";
import {
  INCIDENTS,
  LATENCY_POINTS,
  SERVICES,
  type ServiceId,
  dailyMinutes,
  formatHalfHour,
  latencySeries,
  simulatedIncident,
  statusForMinutes,
  stripDay,
} from "../lib/uptime-status-data";
import { usePointCursor } from "../lib/use-point-cursor";
import { BlockFrame } from "../parts/block-frame";
import { TrendChart } from "../parts/trend-chart";
import { IncidentTimeline } from "./uptime-status/incident-timeline";
import { ServiceRow } from "./uptime-status/service-row";
import { STRIP_HEIGHT } from "./uptime-status/uptime-strip";

const STATES: Status[] = ["good", "watch", "bad"];
const RANK = { good: 0, watch: 1, bad: 2 } satisfies Record<Status, number>;
const STATE_ICON = { good: CircleCheckIcon, watch: AlertTriangleIcon, bad: CircleXIcon } satisfies Record<Status, typeof CircleCheckIcon>;

const milliseconds = (value: number) => `${formatWhole(value)} ms`;

/**
 * A status page: the state of every service now, 90 days of daily bars with
 * uptime, the response time of one service, and the incidents behind the
 * bars. A clearly marked control adds a simulated incident to show each state.
 */
export function UptimeStatus({ className }: { className?: string }) {
  const [selected, setSelected] = useState<ServiceId>("booking");
  const [simulated, setSimulated] = useState<ServiceId | null>(null);
  const cursor = usePointCursor(LATENCY_POINTS, 6);
  const titleId = useId();
  const groupId = useId();

  const incidents = simulated ? [simulatedIncident(simulated), ...INCIDENTS] : INCIDENTS;
  const rows = SERVICES.map((service) => {
    const minutes = dailyMinutes(service.id, incidents);
    return { ...service, minutes, today: statusForMinutes(minutes[minutes.length - 1] ?? 0) };
  });
  const overall = rows.reduce<Status>((worst, row) => (RANK[row.today] > RANK[worst] ? row.today : worst), "good");
  const troubled = rows.filter((row) => row.today !== "good").map((row) => row.name);
  const overallText = overall === "good" ? `All ${rows.length} services good` : `${troubled.join(", ")} ${STATUS_WORD[overall].toLowerCase()}`;
  const OverallIcon = STATE_ICON[overall];

  const service = SERVICES.find((item) => item.id === selected) ?? SERVICES[0]!;
  const latency = latencySeries(service.id, simulated === service.id);
  const average = mean(latency);
  const latencyDetails = (index: number) => {
    const value = latency[index] ?? 0;
    const gap = Math.round(value - average);
    return {
      title: formatHalfHour(index),
      rows: [{ label: "Response time", value: milliseconds(value), marker: "bg-chart-1" }],
      note: gap === 0 ? "At the average" : `${milliseconds(Math.abs(gap))} ${gap > 0 ? "slower" : "faster"} than average`,
    };
  };
  const summary = `${service.name} averaged ${milliseconds(average)} over 24 hours.`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="flex items-center gap-2 text-lg font-semibold">
            <OverallIcon aria-hidden="true" className={cn("size-5 shrink-0", STATUS_TEXT[overall])} />
            <span className="truncate">{overallText}</span>
          </h2>
          <p role="status" className="truncate text-sm text-muted-foreground">
            {simulated ? "Simulation, no clinic is affected" : "Fernhill status, last 90 days"}
          </p>
        </div>
        <Button variant="outline" size="sm" aria-pressed={simulated !== null} onClick={() => setSimulated(simulated ? null : selected)}>
          {simulated ? "End simulation" : "Simulate incident"}
        </Button>
      </header>

      <div className="flex flex-col py-3">
        <RadioGroup
          aria-label="Service shown in the response time chart"
          value={selected}
          onValueChange={(id) => {
            const row = rows.find((item) => item.id === id);
            if (row) setSelected(row.id);
          }}
          className="contents"
        >
          {rows.map((row) => (
            <ServiceRow
              key={row.id}
              name={row.name}
              minutes={row.minutes}
              checked={row.id === selected}
              value={row.id}
              onSelect={() => setSelected(row.id)}
              groupId={groupId}
            />
          ))}
        </RadioGroup>
        <div className="flex flex-col-reverse gap-x-6 gap-y-2 px-5 pt-1 text-xs text-muted-foreground @2xl:grid @2xl:grid-cols-[20rem_1fr]">
          <ul aria-label="Bar key" className="flex gap-x-4">
            {STATES.map((status) => (
              <li key={status} className="flex items-center gap-1.5 whitespace-nowrap">
                <span aria-hidden="true" className={cn("flex h-4 w-1.5 items-end", STATUS_TEXT[status])}>
                  <span className={cn("w-full rounded-sm bg-current", STRIP_HEIGHT[status])} />
                </span>
                {STATUS_WORD[status]}
              </li>
            ))}
          </ul>
          <p aria-hidden="true" className="flex justify-between tabular-nums">
            <span>{stripDay(0)}</span>
            <span>Today</span>
          </p>
        </div>
      </div>

      <div className="grid border-t border-border @3xl:grid-cols-[3fr_2fr]">
        <div className="flex min-w-0 flex-col gap-3 p-5 @3xl:self-start">
          <h3 className="text-sm font-medium">Response time</h3>
          <TrendChart
            label={`${service.name} response time by half hour, last 24 hours`}
            values={latency}
            compare={null}
            axisLabels={[formatHalfHour(0), formatHalfHour(Math.floor(LATENCY_POINTS / 2)), formatHalfHour(LATENCY_POINTS - 1)]}
            formatAxis={formatWhole}
            describePoint={(index) => `${formatHalfHour(index)}: ${milliseconds(latency[index] ?? 0)}.`}
            pointDetails={latencyDetails}
            summary={summary}
            cursor={cursor}
          />
        </div>
        <div className="flex min-w-0 flex-col gap-3 border-t border-border p-5 @3xl:border-t-0 @3xl:border-l">
          <h3 className="text-sm font-medium">Incidents</h3>
          <IncidentTimeline incidents={incidents} />
        </div>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

import { formatDay, sampleDate } from "./format";
import { makeSeries } from "./plot";
import type { Status } from "./status";

/** The parts of Fernhill a clinic depends on. */
export type ServiceId = "booking" | "calendar" | "reminders" | "records" | "signin";

/** One service on the status page. */
export interface Service {
  id: ServiceId;
  name: string;
}

/** One incident: which service it hit, when, and for how long. */
export interface Incident {
  id: string;
  serviceId: ServiceId;
  /** Days before the last sample day. 0 is today. */
  daysAgo: number;
  /** Minutes the service was down or slow. */
  minutes: number;
  /** At most six words. */
  title: string;
  /** Set on the incident the simulate control adds. It is not part of the record. */
  simulated?: boolean;
}

/** How many days each strip shows. */
export const UPTIME_DAYS = 90;

/** How many half hours the response time chart shows: one day. */
export const LATENCY_POINTS = 48;

/** The services in page order. */
export const SERVICES: Service[] = [
  { id: "booking", name: "Booking page" },
  { id: "calendar", name: "Clinic calendar" },
  { id: "reminders", name: "Reminders" },
  { id: "records", name: "Patient records" },
  { id: "signin", name: "Sign-in" },
];

/** The recorded incidents, newest first. Every strip and uptime figure is worked out from this list. */
export const INCIDENTS: Incident[] = [
  { id: "i7", serviceId: "reminders", daysAgo: 7, minutes: 47, title: "Reminder texts sent late" },
  { id: "i6", serviceId: "booking", daysAgo: 19, minutes: 12, title: "Booking page slow to load" },
  { id: "i5", serviceId: "calendar", daysAgo: 26, minutes: 64, title: "Calendar changes did not save" },
  { id: "i4", serviceId: "signin", daysAgo: 33, minutes: 8, title: "Sign-in codes arrived late" },
  { id: "i3", serviceId: "records", daysAgo: 41, minutes: 22, title: "Patient search slow" },
  { id: "i2", serviceId: "booking", daysAgo: 58, minutes: 35, title: "Booking page down" },
  { id: "i1", serviceId: "signin", daysAgo: 83, minutes: 26, title: "Some staff could not sign in" },
];

/** The incident the simulate control adds to a service. */
export function simulatedIncident(serviceId: ServiceId): Incident {
  return {
    id: "simulated",
    serviceId,
    daysAgo: 0,
    minutes: 38,
    title: "Simulated outage",
    simulated: true,
  };
}

/** The state of a day from its minutes of trouble: none is good, under half an hour is watch, more is at risk. */
export function statusForMinutes(minutes: number): Status {
  if (minutes === 0) return "good";
  return minutes < 30 ? "watch" : "bad";
}

/** Minutes of trouble on each of the 90 days for one service, oldest first. */
export function dailyMinutes(serviceId: ServiceId, incidents: Incident[]): number[] {
  const days = Array.from({ length: UPTIME_DAYS }, () => 0);
  for (const incident of incidents) {
    const index = UPTIME_DAYS - 1 - incident.daysAgo;
    if (incident.serviceId === serviceId && index >= 0) days[index] = (days[index] ?? 0) + incident.minutes;
  }
  return days;
}

/** The share of the 90 days a service was up, as a percent. */
export function uptimePercent(minutes: number[]): number {
  const down = minutes.reduce((total, value) => total + value, 0);
  return 100 - (down / (minutes.length * 1440)) * 100;
}

/** An uptime percent with two decimal places, such as 99.95%. */
export const formatUptime = (value: number) => `${value.toFixed(2)}%`;

/** The date of a strip day, where index 0 is the oldest day. */
export const stripDay = (index: number) => formatDay(sampleDate(UPTIME_DAYS - 1 - index));

// Typical response time in milliseconds at the start and end of the day, and how much it wanders.
const LATENCY = {
  booking: [211, 184, 196, 44],
  calendar: [223, 142, 138, 30],
  reminders: [239, 268, 251, 60],
  records: [251, 221, 230, 52],
  signin: [263, 96, 92, 20],
} satisfies Record<ServiceId, [seed: number, start: number, end: number, noise: number]>;

/** Response time for each half hour of the last day. A simulated incident lifts the last three points. */
export function latencySeries(serviceId: ServiceId, simulated: boolean): number[] {
  const [seed, start, end, noise] = LATENCY[serviceId];
  const values = makeSeries(seed, LATENCY_POINTS, start, end, noise).map(Math.round);
  if (!simulated) return values;
  return values.map((value, index) => (index >= LATENCY_POINTS - 3 ? Math.round(value * (2.4 + (index - (LATENCY_POINTS - 3)) * 0.9)) : value));
}

// The chart ends at 14:00 on the last sample day.
const END_MINUTE = 14 * 60;

/** The clock time of a half hour point, with the date when it falls on the day before. */
export function formatHalfHour(index: number): string {
  const offset = END_MINUTE - (LATENCY_POINTS - 1 - index) * 30;
  const minute = (offset + 1440) % 1440;
  const clock = `${String(Math.floor(minute / 60)).padStart(2, "0")}:${String(minute % 60).padStart(2, "0")}`;
  return offset < 0 ? `${formatDay(sampleDate(1))}, ${clock}` : clock;
}

"use client";

import { type KeyboardEvent, type PointerEvent, useCallback, useState } from "react";

/** What a chart needs to let a person inspect one point with a pointer or the keyboard. */
export interface PointCursor {
  /** The inspected point, or null when nothing is inspected. */
  index: number | null;
  setIndex: (index: number | null) => void;
  /** Spread onto the focusable plot. Arrows step, Page keys jump, Home and End go to the ends, Escape clears. */
  plotProps: {
    tabIndex: 0;
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
    /** A tap or a press inspects the point under it, so a touch screen needs no hover. */
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerLeave: (event: PointerEvent<HTMLElement>) => void;
    /** A finger can scrub across the plot while the page still scrolls up and down. */
    style: { touchAction: "pan-y" };
    onBlur: () => void;
  };
}

/**
 * Tracks the inspected point of a plot with `length` points. `pageStep` is how
 * far the Page keys and Shift with an arrow jump.
 */
export function usePointCursor(length: number, pageStep = 7): PointCursor {
  const [raw, setIndex] = useState<number | null>(null);
  // A shorter range can leave the cursor past the end, so clamp on read.
  const index = raw === null ? null : Math.min(raw, length - 1);

  const onKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>) => {
      const last = length - 1;
      const current = index ?? last;
      const big = event.shiftKey ? pageStep : 1;
      let next: number | null;
      if (event.key === "ArrowLeft") next = index === null ? last : Math.max(0, current - big);
      else if (event.key === "ArrowRight") next = index === null ? last : Math.min(last, current + big);
      else if (event.key === "PageUp") next = Math.max(0, current - pageStep);
      else if (event.key === "PageDown") next = Math.min(last, current + pageStep);
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = last;
      else if (event.key === "Escape" && index !== null) next = null;
      else return;
      event.preventDefault();
      setIndex(next);
    },
    [index, length, pageStep],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      const box = event.currentTarget.getBoundingClientRect();
      if (box.width === 0) return;
      const ratio = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
      setIndex(Math.round(ratio * (length - 1)));
    },
    [length],
  );

  const clear = useCallback(() => setIndex(null), []);

  // A finger leaves the plot the moment it lifts. Clearing then would hide the point a tap just chose,
  // so only a mouse clears on the way out. A tapped point stays until the plot loses focus.
  const onPointerLeave = useCallback((event: PointerEvent<HTMLElement>) => {
    if (event.pointerType === "mouse") setIndex(null);
  }, []);

  return {
    index,
    setIndex,
    plotProps: {
      tabIndex: 0,
      onKeyDown,
      onPointerDown: onPointerMove,
      onPointerMove,
      onPointerLeave,
      onBlur: clear,
      style: { touchAction: "pan-y" },
    },
  };
}

