  return (
    <ol className={cn("flex flex-col gap-1", className)}>
      {incidents.slice(0, INCIDENTS_SHOWN).map((incident) => {
        const service = SERVICES.find((item) => item.id === incident.serviceId);
        return (
          <li key={incident.id} className="grid grid-cols-[1fr_auto] items-center gap-x-3 gap-y-0.5 py-2.5 first:pt-0 last:pb-0">
