import { UptimeStrip } from "./uptime-strip";

// Two decimal places, the same text as `formatUptime` without its percent sign.
const UPTIME_ROLL: Intl.NumberFormatOptions = { minimumFractionDigits: 2, maximumFractionDigits: 2 };

/** Props for one service on the status page. */
export interface ServiceRowProps {
  name: string;
  /** Minutes of trouble on each day, oldest first. The last day is today. */
  minutes: number[];
  /** Whether this service is the one in the response time chart. */
  checked: boolean;
  /** The radio value, which the group hands back when this service is chosen. */
  value: string;
  onSelect: () => void;
  /** Shared by every row in the group, so the highlight moves between rows. */
  groupId: string;
}

/**
 * One service: a radio card with its name, state now and 90 day uptime in
 * fixed columns, then its strip of daily bars. Choosing the card charts the service.
 */
export function ServiceRow({ name, minutes, checked, value, onSelect, groupId }: ServiceRowProps) {
  const reduceMotion = useReducedMotion();
  const today = statusForMinutes(minutes[minutes.length - 1] ?? 0);

  return (
    <div className="relative grid gap-x-6 gap-y-2 px-5 py-3 @2xl:grid-cols-[20rem_1fr] @2xl:items-center">
      {checked ? (
        <motion.span
          layoutId={`${groupId}-highlight`}
          aria-hidden="true"
          // Critically damped: 2 * sqrt(420) is about 41.
          transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 420, damping: 41, mass: 1 }}
          className="absolute inset-0 bg-muted/60"
        />
      ) : null}
      <label className="relative flex min-h-11 cursor-pointer items-center gap-3 rounded-md outline-none has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-offset-2 has-focus-visible:ring-offset-card sm:min-h-9">
        <RadioGroupItem value={value} />
        <span className="grid min-w-0 flex-1 grid-cols-[1fr_4.5rem_3.5rem] items-center gap-x-3">
          <span className="truncate text-sm font-medium">{name}</span>
          <StatusMark status={today} />
          <span className="text-right text-sm tabular-nums">
            <NumberTicker value={uptimePercent(minutes)} format={UPTIME_ROLL} />%
            <span className="sr-only"> uptime over 90 days</span>
          </span>
        </span>
      </label>
      <UptimeStrip name={name} minutes={minutes} onSelect={onSelect} className="relative" />
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";

import { STATUS_TEXT, STATUS_WORD, type Status } from "../../lib/status";
import { statusForMinutes, stripDay } from "../../lib/uptime-status-data";
import { usePointCursor } from "../../lib/use-point-cursor";
import { PointTip } from "../../parts/point-tip";

/** Props for a strip of daily bars. */
export interface UptimeStripProps {
  /** The service name, used in the strip's spoken label. */
  name: string;
  /** Minutes of trouble on each day, oldest first. */
  minutes: number[];
  /** Called on Enter, Space or a click, to chart this service. */
  onSelect: () => void;
  className?: string;
}

/** The bar height for each state. A day with trouble is a shorter bar, so the strip reads without colour. */
export const STRIP_HEIGHT = { good: "h-full", watch: "h-3/5", bad: "h-1/4" } satisfies Record<Status, string>;

function describeDay(minutes: number[], index: number): string {
  const value = minutes[index] ?? 0;
  const word = STATUS_WORD[statusForMinutes(value)];
  return `${stripDay(index)}: ${word}${value === 0 ? ", no trouble recorded" : `, ${value} minutes of trouble`}.`;
}

/**
 * Ninety daily bars for one service. The strip is one tab stop: arrows move
 * a day, Page keys a week, Home and End jump, Escape clears, and Enter or
 * Space charts the service. The inspected day keeps its colour while the
 * other days fade, and it gets a card with its date, state and minutes of trouble.
 */
export function UptimeStrip({ name, minutes, onSelect, className }: UptimeStripProps) {
  const cursor = usePointCursor(minutes.length);
  const { index, plotProps } = cursor;
  const value = index === null ? 0 : (minutes[index] ?? 0);
  const status = statusForMinutes(value);
  const across = index === null ? 0 : ((index + 0.5) / minutes.length) * 100;

  return (
    <div className={cn("min-w-0", className)}>
      <div
        {...plotProps}
        role="application"
        aria-roledescription="daily status strip"
        aria-label={`${name}, last ${minutes.length} days. Arrow keys read each day. Enter shows this service in the chart.`}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            onSelect();
            return;
          }
          plotProps.onKeyDown(event);
        }}
        onClick={onSelect}
        className="relative flex h-11 cursor-pointer touch-pan-y items-end gap-px rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card sm:h-8"
      >
        {minutes.map((dayValue, day) => {
          const dayStatus = statusForMinutes(dayValue);
          return (
            <span
              key={day}
              aria-hidden="true"
              className={cn(
                "min-w-0 flex-1 rounded-sm bg-current motion-safe:transition-opacity motion-safe:duration-150",
                STATUS_TEXT[dayStatus],
                STRIP_HEIGHT[dayStatus],
                index === null || index === day ? "opacity-100" : "opacity-30",
              )}
            />
          );
        })}
        {index === null ? null : (
          <PointTip
            x={across}
            y={50}
            title={`${name}, ${stripDay(index)}`}
            rows={[
              { label: "State", value: STATUS_WORD[status], marker: cn("bg-current", STATUS_TEXT[status]) },
              { label: "Trouble", value: value === 0 ? "None" : `${value} min` },
            ]}
          />
        )}
      </div>
      <p aria-live="polite" className="sr-only">
        {index === null ? "" : describeDay(minutes, index)}
      </p>
    </div>
  );
}
